import React, { useMemo, useState, useCallback, useEffect } from "react";
import {
  Package, ChevronDown, ChevronRight, Save, Search,
  CheckCircle2, Circle, Layers, Zap, Filter, X, Loader2,
  AlertTriangle, Check
} from 'lucide-react';
import { useApiData, useModalValues } from '../hooks/useApiData';
import { useStore } from '../contexts/StoreContext';

function InputModal() {
  const { activeStoreId } = useStore();
  const { data: ordersData, loading: loadingOrders } = useApiData('skuCatalog', activeStoreId);
  const { modalValues, setModalValues, loading: loadingModal, saveAll } = useModalValues(activeStoreId);

  // ─── Responsive State ──────────────────────────────────────────────
  const [windowWidth, setWindowWidth] = useState(() => (typeof window !== 'undefined' ? window.innerWidth : 1200));
  useEffect(() => {
    function handleResize() { setWindowWidth(window.innerWidth); }
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);
  const isMobile = windowWidth < 768;

  // ─── Data Processing ───────────────────────────────────────────────
  const skuIdToChannel = useMemo(() => {
    const map = new Map();
    const sellerSkuToChannel = new Map();
    ordersData.forEach((order) => {
      const skuIdRaw = order["SKU ID"];
      const sellerSkuRaw = order["Seller SKU"];
      const channel = order["Channel Marketplace"] || "";
      if (skuIdRaw !== undefined && skuIdRaw !== null) {
        const skuId = skuIdRaw.toString().trim();
        if (skuId) map.set(skuId, channel);
      }
      if (sellerSkuRaw !== undefined && sellerSkuRaw !== null) {
        const sellerSku = sellerSkuRaw.toString().trim();
        if (sellerSku) sellerSkuToChannel.set(sellerSku, channel);
      }
    });
    return { skuIdToChannel: map, sellerSkuToChannel };
  }, [ordersData]);

  const platformIcons = {
    Tiktok: "https://static.vecteezy.com/system/resources/previews/023/986/939/non_2x/tiktok-logo-tiktok-logo-transparent-tiktok-icon-transparent-free-free-png.png",
    Shopee: "https://static.vecteezy.com/system/resources/previews/053/407/516/non_2x/shopee-logo-shopee-icon-transparent-social-media-icons-free-png.png",
    Lazada: "https://static.cdnlogo.com/logos/l/48/lazada-icon800x800.png",
    Tokopedia: "https://freelogopng.com/images/all_img/1691990957tokopedia-icon-png.png",
    Unknown: "https://icons.iconarchive.com/icons/custom-icon-design/flatastic-1/512/delete-icon.png",
  };

  const groupedBySellerSku = useMemo(() => {
    const map = new Map();
    ordersData.forEach((order) => {
      const sellerSkuRaw = order['Seller SKU'];
      const skuIdRaw = order['SKU ID'];
      const variationRaw = order['Variation'];
      const productName = order['Product Name'] || '';
      const sellerSku = sellerSkuRaw ? sellerSkuRaw.toString().trim() : '';
      const skuId = skuIdRaw !== undefined && skuIdRaw !== null ? skuIdRaw.toString().trim() : '';
      const variation = variationRaw !== undefined && variationRaw !== null ? variationRaw.toString().trim() : '';
      // Use sellerSku as key, or fallback to Product Name for products without SKU
      const key = sellerSku || (productName ? '__NSKU__' + productName : '');
      if (key === '') return;
      if (!map.has(key)) map.set(key, { sellerSku: key, productName, noSku: !sellerSku, variations: [] });
      const entry = map.get(key);
      if (!entry.productName && productName) entry.productName = productName;
      const variations = entry.variations;
      if (!variations.some(v => v.skuId === skuId && v.variation === variation)) {
        variations.push({ skuId, variation });
      }
    });
    for (const val of map.values()) {
      val.variations.sort((a, b) => {
        const skuCompare = a.skuId.localeCompare(b.skuId);
        if (skuCompare !== 0) return skuCompare;
        return a.variation.localeCompare(b.variation);
      });
    }
    return Array.from(map.values()).sort((a, b) => {
      // Products with SKU first, then no-SKU
      if (a.noSku !== b.noSku) return a.noSku ? 1 : -1;
      return a.sellerSku.localeCompare(b.sellerSku);
    });
  }, [ordersData]);

  // ─── State ─────────────────────────────────────────────────────────
  const [expandedSkus, setExpandedSkus] = useState(new Set());
  const [bulkInputs, setBulkInputs] = useState({});
  const [searchQuery, setSearchQuery] = useState('');
  const [filterMode, setFilterMode] = useState('all'); // all | filled | unfilled
  const [flashSaved, setFlashSaved] = useState(null);
  const [isDirty, setIsDirty] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // ─── Save all to DB ───────────────────────────────────────────────
  async function handleSaveAll() {
    setIsSaving(true);
    try {
      const toSave = {};
      Object.entries(modalValues).forEach(([key, val]) => {
        const num = String(val).replace(/[^0-9]/g, '');
        toSave[key] = num || '0';
      });
      await saveAll(toSave);
      setIsDirty(false);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
    } catch {
      // ignore
    }
    setIsSaving(false);
  }

  // ─── Helpers ───────────────────────────────────────────────────────
  function getVariationTypes(variations) {
    if (!variations || variations.length === 0) return [];
    const allVariations = variations.map(v => v.variation);
    const splitBySlash = allVariations.map(v => v.split(' / '));
    const maxParts = Math.max(...splitBySlash.map(arr => arr.length));
    if (maxParts > 1) {
      const variationTypes = [];
      for (let i = 0; i < maxParts; i++) {
        const vals = new Set();
        splitBySlash.forEach(arr => { if (arr[i]) vals.add(arr[i].trim()); });
        variationTypes.push({ index: i, values: Array.from(vals).sort() });
      }
      return variationTypes;
    }
    const splitByComma = allVariations.map(v => v.split(','));
    const maxPartsComma = Math.max(...splitByComma.map(arr => arr.length));
    if (maxPartsComma > 1) {
      const variationTypes = [];
      for (let i = 0; i < maxPartsComma; i++) {
        const vals = new Set();
        splitByComma.forEach(arr => { if (arr[i]) vals.add(arr[i].trim()); });
        variationTypes.push({ index: i, values: Array.from(vals).sort() });
      }
      return variationTypes;
    }
    return [];
  }

  function toggleExpand(sku) {
    setExpandedSkus((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(sku)) {
        newSet.delete(sku);
        setBulkInputs((prevBulk) => { const newBulk = { ...prevBulk }; delete newBulk[sku]; return newBulk; });
      } else {
        newSet.add(sku);
        setBulkInputs((prevBulk) => {
          if (prevBulk[sku]) return prevBulk;
          return { ...prevBulk, [sku]: { selections: [], value: '' } };
        });
      }
      return newSet;
    });
  }

  function handleMainInputChange(sellerSku, e) {
    let value = e.target.value;
    let numericValue = value.toString().replace(/[^0-9]/g, '');
    if (numericValue === '') {
      setModalValues((prev) => { const newObj = { ...prev }; delete newObj[sellerSku]; return newObj; });
      setIsDirty(true);
      return;
    }
    if (numericValue.length > 15) numericValue = numericValue.slice(0, 15);
    const formatted = 'Rp' + Number(numericValue).toLocaleString('id-ID');
    setModalValues((prev) => ({ ...prev, [sellerSku]: formatted }));
    setIsDirty(true);
  }

  function handleVariationInputChange(sellerSku, skuId, variation, e) {
    let value = e.target.value;
    let numericValue = value.toString().replace(/[^0-9]/g, '');
    const key = sellerSku + '||' + skuId + '||' + variation;
    if (numericValue === '') {
      setModalValues((prev) => {
        const newObj = { ...prev };
        delete newObj[key];
        return newObj;
      });
      setIsDirty(true);
      return;
    }
    if (numericValue.length > 15) numericValue = numericValue.slice(0, 15);
    const formatted = 'Rp' + Number(numericValue).toLocaleString('id-ID');
    setModalValues((prev) => {
      const newObj = { ...prev };
      newObj[key] = formatted;
      if (newObj[sellerSku]) delete newObj[sellerSku];
      return newObj;
    });
    setIsDirty(true);
  }

  const filledVariationCountBySku = useMemo(() => {
    const counts = new Map();
    for (const k of Object.keys(modalValues)) {
      const sepIdx = k.indexOf('||');
      if (sepIdx > 0 && modalValues[k]) {
        const sku = k.slice(0, sepIdx);
        counts.set(sku, (counts.get(sku) || 0) + 1);
      }
    }
    return counts;
  }, [modalValues]);

  const invalidSkus = useMemo(() => {
    const invalidSet = new Set();
    groupedBySellerSku.forEach(({ sellerSku, variations }) => {
      const filledCount = filledVariationCountBySku.get(sellerSku) || 0;
      if (filledCount > 0 && filledCount < variations.length) invalidSet.add(sellerSku);
    });
    return invalidSet;
  }, [groupedBySellerSku, filledVariationCountBySku]);

  function hasAnyVariationFilled(sellerSku) {
    return (filledVariationCountBySku.get(sellerSku) || 0) > 0;
  }

  function handleBulkDropdownChange(sellerSku, index, value) {
    setBulkInputs((prev) => {
      const prevEntry = prev[sellerSku] || { selections: [], value: '' };
      const newSelections = [...prevEntry.selections];
      newSelections[index] = value;
      return { ...prev, [sellerSku]: { ...prevEntry, selections: newSelections } };
    });
  }

  function handleBulkValueChange(sellerSku, e) {
    let value = e.target.value;
    let numericValue = value.toString().replace(/[^0-9]/g, '');
    if (numericValue.length > 15) numericValue = numericValue.slice(0, 15);
    const formatted = numericValue === '' ? '' : 'Rp' + Number(numericValue).toLocaleString('id-ID');
    setBulkInputs((prev) => {
      const prevEntry = prev[sellerSku] || { selections: [], value: '' };
      return { ...prev, [sellerSku]: { ...prevEntry, value: formatted } };
    });
  }

  function applyBulkInput(sellerSku) {
    const bulk = bulkInputs[sellerSku];
    if (!bulk || !bulk.value) return;
    const variations = groupedBySellerSku.find(g => g.sellerSku === sellerSku)?.variations || [];
    if (variations.length === 0) return;
    const variationTypes = getVariationTypes(variations);
    const selections = bulk.selections || [];
    const keysToUpdate = [];

    variations.forEach(({ skuId, variation }) => {
      if (variationTypes.length === 0) {
        keysToUpdate.push(sellerSku + '||' + skuId + '||' + variation);
      } else {
        let parts = variation.split(' / ');
        if (parts.length === 1) parts = variation.split(',');
        parts = parts.map(p => p.trim());
        if (parts.length !== variationTypes.length) {
          keysToUpdate.push(sellerSku + '||' + skuId + '||' + variation);
        } else {
          let match = true;
          for (let i = 0; i < variationTypes.length; i++) {
            const sel = selections[i] || 'Semua Variasi';
            if (sel !== 'Semua Variasi' && sel !== parts[i]) { match = false; break; }
          }
          if (match) keysToUpdate.push(sellerSku + '||' + skuId + '||' + variation);
        }
      }
    });

    if (keysToUpdate.length === 0) return;
    setModalValues((prev) => {
      const newObj = { ...prev };
      if (newObj[sellerSku]) delete newObj[sellerSku];
      keysToUpdate.forEach((key) => {
        newObj[key] = bulk.value;
      });
      return newObj;
    });
    setIsDirty(true);

    // Flash saved feedback
    setFlashSaved(sellerSku);
    setTimeout(() => setFlashSaved(null), 1500);
  }

  // ─── Computed Stats & Filtering ────────────────────────────────────
  const getSkuFillStatus = useCallback((sellerSku, variations) => {
    if (modalValues[sellerSku]) return 'filled';
    const filledCount = filledVariationCountBySku.get(sellerSku) || 0;
    if (filledCount >= variations.length && filledCount > 0) return 'filled';
    if (filledCount > 0) return 'partial';
    return 'unfilled';
  }, [modalValues, filledVariationCountBySku]);

  const stats = useMemo(() => {
    let filled = 0, partial = 0, unfilled = 0;
    groupedBySellerSku.forEach(({ sellerSku, variations }) => {
      const status = getSkuFillStatus(sellerSku, variations);
      if (status === 'filled') filled++;
      else if (status === 'partial') partial++;
      else unfilled++;
    });
    return { filled, partial, unfilled, total: groupedBySellerSku.length };
  }, [groupedBySellerSku, getSkuFillStatus]);

  const filteredSkus = useMemo(() => {
    let items = groupedBySellerSku;
    // Search filter
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      items = items.filter(({ sellerSku, productName }) =>
        sellerSku.toLowerCase().includes(q) ||
        (productName && productName.toLowerCase().includes(q))
      );
    }
    // Fill status filter
    if (filterMode !== 'all') {
      items = items.filter(({ sellerSku, variations }) => {
        const status = getSkuFillStatus(sellerSku, variations);
        if (filterMode === 'filled') return status === 'filled';
        if (filterMode === 'unfilled') return status === 'unfilled' || status === 'partial';
        return true;
      });
    }
    return items;
  }, [groupedBySellerSku, searchQuery, filterMode, getSkuFillStatus]);

  // Channel icon helper
  function getChannelIcon(sellerSku, variations) {
    let ch = "";
    if (variations.length > 0) {
      ch = skuIdToChannel.skuIdToChannel.get(variations[0].skuId) || "";
      if (!ch) ch = skuIdToChannel.sellerSkuToChannel.get(sellerSku) || "";
    }
    if (!ch) return null;
    const iconSrc = platformIcons[ch.charAt(0).toUpperCase() + ch.slice(1).toLowerCase()] || platformIcons.Unknown;
    return { iconSrc, channel: ch };
  }

  // Progress percentage
  const progressPercent = stats.total > 0 ? Math.round((stats.filled / stats.total) * 100) : 0;

  // Toggle expand all
  const allExpanded = useMemo(() => {
    const multiVarSkus = filteredSkus.filter(g => g.variations.length > 1);
    return multiVarSkus.length > 0 && multiVarSkus.every(g => expandedSkus.has(g.sellerSku));
  }, [filteredSkus, expandedSkus]);

  const toggleExpandAll = () => {
    const multiVarSkus = filteredSkus.filter(g => g.variations.length > 1);
    if (allExpanded) {
      setExpandedSkus(prev => {
        const next = new Set(prev);
        multiVarSkus.forEach(g => next.delete(g.sellerSku));
        return next;
      });
    } else {
      setExpandedSkus(prev => {
        const next = new Set(prev);
        multiVarSkus.forEach(g => next.add(g.sellerSku));
        return next;
      });
    }
  };

  // Keyboard Navigation: Enter advances to next input
  const handleInputKeyDown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const inputs = Array.from(document.querySelectorAll('.im-table-input:not([disabled])'));
      const index = inputs.indexOf(e.target);
      if (index >= 0 && index < inputs.length - 1) {
        inputs[index + 1].focus();
        inputs[index + 1].select();
      }
    }
  };

  // ─── Loading State ─────────────────────────────────────────────────
  if (loadingOrders || loadingModal) {
    return (
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          height: isMobile ? 'calc(100vh - 8.35rem)' : 'calc(100vh - 1.3rem)',
          overflow: 'hidden',
        }}
      >
        {/* Skeleton Header */}
        <div
          style={{
            flexShrink: 0,
            background: '#ffffff',
            borderRadius: '12px',
            border: '1px solid #e2e8f0',
            padding: '0.6rem 0.85rem',
            marginBottom: '0.5rem',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.65rem' }}>
            <div className="skeleton" style={{ width: 32, height: 32, borderRadius: '8px' }} />
            <div>
              <div className="skeleton" style={{ width: 120, height: 18, marginBottom: 4 }} />
              <div className="skeleton" style={{ width: 70, height: 12 }} />
            </div>
          </div>
          <div className="skeleton" style={{ width: 180, height: 34, borderRadius: '8px' }} />
        </div>

        {/* Skeleton Table Card */}
        <div
          className="modern-table-wrapper"
          style={{
            flex: 1,
            minHeight: 0,
            background: '#ffffff',
            borderRadius: '12px',
            border: '1px solid #e2e8f0',
            overflow: 'hidden',
            display: 'flex',
            flexDirection: 'column',
          }}
        >
          <div style={{ flex: 1, minHeight: 0, overflow: 'auto', padding: '1rem' }}>
            {Array.from({ length: 8 }).map((_, i) => (
              <div
                key={`skel-row-${i}`}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '1rem',
                  padding: '0.75rem 0.5rem',
                  borderBottom: '1px solid #f1f5f9',
                }}
              >
                <div className="skeleton" style={{ width: 30, height: 16 }} />
                <div className="skeleton" style={{ width: 24, height: 24, borderRadius: '4px' }} />
                <div className="skeleton" style={{ flex: 1, height: 16 }} />
                <div className="skeleton" style={{ width: 90, height: 22, borderRadius: '9999px' }} />
                <div className="skeleton" style={{ width: 120, height: 30, borderRadius: '6px' }} />
                <div className="skeleton" style={{ width: 70, height: 20, borderRadius: '9999px' }} />
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // ─── RENDER ────────────────────────────────────────────────────────
  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        height: isMobile ? 'calc(100vh - 8.35rem)' : 'calc(100vh - 1.3rem)',
        overflow: 'hidden',
      }}
    >
      {/* ── Top Header Toolbar (Separate Card) ── */}
      <div
        style={{
          flexShrink: 0,
          background: '#ffffff',
          borderRadius: '12px',
          border: '1px solid #e2e8f0',
          boxShadow: '0 1px 3px rgba(0, 0, 0, 0.04), 0 1px 2px rgba(0, 0, 0, 0.02)',
          padding: isMobile ? '0.55rem 0.65rem' : '0.55rem 0.85rem',
          marginBottom: '0.5rem',
          display: 'flex',
          flexDirection: isMobile ? 'column' : 'row',
          alignItems: isMobile ? 'stretch' : 'center',
          justifyContent: 'space-between',
          gap: isMobile ? '0.5rem' : '0.85rem',
        }}
      >
        {/* Sisi Kiri: Icon + Judul + Badges */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: isMobile ? 'space-between' : 'flex-start', gap: '0.65rem', flexShrink: 0, flexWrap: 'wrap' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.45rem' }}>
            <div
              style={{
                width: isMobile ? 28 : 32,
                height: isMobile ? 28 : 32,
                borderRadius: '8px',
                background: 'linear-gradient(135deg, #6366f1, #8b5cf6)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: '#ffffff',
                flexShrink: 0,
                boxShadow: '0 2px 6px rgba(99, 102, 241, 0.22)',
              }}
            >
              <Package size={isMobile ? 15 : 17} strokeWidth={2.3} />
            </div>
            <div>
              <h2
                style={{
                  margin: 0,
                  fontSize: isMobile ? '0.925rem' : '1.025rem',
                  fontWeight: 800,
                  color: '#0f172a',
                  letterSpacing: '-0.02em',
                  lineHeight: 1.2,
                }}
              >
                Input HPP
              </h2>
            </div>
          </div>

          {/* Badges */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.35rem', flexWrap: 'wrap' }}>
            <span
              style={{
                fontSize: '0.725rem',
                fontWeight: 600,
                color: '#475569',
                background: '#f1f5f9',
                border: '1px solid #e2e8f0',
                padding: '2px 8px',
                borderRadius: '9999px',
                whiteSpace: 'nowrap',
              }}
            >
              {stats.total} SKU
            </span>
            <span
              style={{
                fontSize: '0.725rem',
                fontWeight: 600,
                color: '#059669',
                background: '#ecfdf5',
                border: '1px solid #a7f3d0',
                padding: '2px 8px',
                borderRadius: '9999px',
                whiteSpace: 'nowrap',
                display: 'inline-flex',
                alignItems: 'center',
                gap: '3px',
              }}
            >
              <CheckCircle2 size={12} /> {stats.filled} terisi
            </span>
            {(stats.unfilled + stats.partial) > 0 && (
              <span
                style={{
                  fontSize: '0.725rem',
                  fontWeight: 600,
                  color: '#d97706',
                  background: '#fffbeb',
                  border: '1px solid #fde68a',
                  padding: '2px 8px',
                  borderRadius: '9999px',
                  whiteSpace: 'nowrap',
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: '3px',
                }}
              >
                <Circle size={10} /> {stats.unfilled + stats.partial} belum
              </span>
            )}
          </div>

          {/* Mini Progress Bar */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.45rem', minWidth: '90px' }}>
            <div style={{ width: '70px', height: '6px', background: '#e2e8f0', borderRadius: '9999px', overflow: 'hidden' }}>
              <div
                style={{
                  height: '100%',
                  width: `${progressPercent}%`,
                  background: progressPercent === 100 ? '#10b981' : 'linear-gradient(90deg, #6366f1, #8b5cf6)',
                  borderRadius: '9999px',
                  transition: 'width 0.4s ease',
                }}
              />
            </div>
            <span style={{ fontSize: '0.7rem', fontWeight: 700, color: progressPercent === 100 ? '#059669' : '#6366f1' }}>
              {progressPercent}%
            </span>
          </div>
        </div>

        {/* Sisi Kanan: Search Bar + Filter Tabs + Toggle Expand All + Save Button */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '0.45rem',
            flexWrap: isMobile ? 'wrap' : 'nowrap',
            width: isMobile ? '100%' : 'auto',
            justifyContent: isMobile ? 'stretch' : 'flex-end',
          }}
        >
          {/* Search Input */}
          <div style={{ position: 'relative', width: isMobile ? '100%' : '190px', flexShrink: 0 }}>
            <Search
              size={14}
              style={{
                position: 'absolute',
                left: '0.75rem',
                top: '50%',
                transform: 'translateY(-50%)',
                color: searchQuery ? '#6366f1' : '#94a3b8',
                pointerEvents: 'none',
              }}
            />
            <input
              type="text"
              placeholder="Cari SKU..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              style={{
                width: '100%',
                height: '34px',
                padding: '0 1.8rem 0 2.2rem',
                borderRadius: '8px',
                border: searchQuery ? '1px solid #6366f1' : '1px solid #cbd5e1',
                background: searchQuery ? '#f5f3ff' : '#f8fafc',
                color: '#0f172a',
                fontSize: '0.775rem',
                fontWeight: 500,
                outline: 'none',
                transition: 'all 0.15s ease',
              }}
            />
            {searchQuery && (
              <button
                type="button"
                onClick={() => setSearchQuery('')}
                style={{
                  position: 'absolute',
                  right: '0.55rem',
                  top: '50%',
                  transform: 'translateY(-50%)',
                  background: 'none',
                  border: 'none',
                  cursor: 'pointer',
                  color: '#94a3b8',
                  padding: '0.15rem',
                  display: 'flex',
                }}
              >
                <X size={13} />
              </button>
            )}
          </div>

          {/* Filter Segmented Buttons */}
          <div
            style={{
              display: 'inline-flex',
              background: '#f1f5f9',
              borderRadius: '8px',
              padding: '2px',
              border: '1px solid #e2e8f0',
              height: '34px',
              alignItems: 'center',
            }}
          >
            {[
              { key: 'all', label: 'Semua', count: stats.total },
              { key: 'unfilled', label: 'Belum', count: stats.unfilled + stats.partial },
              { key: 'filled', label: 'Terisi', count: stats.filled },
            ].map((tab) => {
              const isActive = filterMode === tab.key;
              return (
                <button
                  key={tab.key}
                  type="button"
                  onClick={() => setFilterMode(tab.key)}
                  style={{
                    border: 'none',
                    background: isActive ? '#ffffff' : 'transparent',
                    color: isActive ? '#4f46e5' : '#64748b',
                    fontWeight: isActive ? 700 : 500,
                    fontSize: '0.725rem',
                    padding: '0 0.55rem',
                    height: '28px',
                    borderRadius: '6px',
                    cursor: 'pointer',
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: '4px',
                    boxShadow: isActive ? '0 1px 2px rgba(0,0,0,0.06)' : 'none',
                    transition: 'all 0.15s ease',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {tab.label}
                  <span style={{ fontSize: '0.675rem', opacity: isActive ? 0.9 : 0.6 }}>({tab.count})</span>
                </button>
              );
            })}
          </div>

          {/* Toggle Expand All Multi-Variations */}
          <button
            type="button"
            onClick={toggleExpandAll}
            title={allExpanded ? "Tutup Semua Variasi" : "Buka Semua Variasi"}
            style={{
              height: '34px',
              display: 'inline-flex',
              alignItems: 'center',
              gap: '0.35rem',
              padding: '0 0.65rem',
              borderRadius: '8px',
              border: '1px solid #e2e8f0',
              background: allExpanded ? '#eef2ff' : '#f8fafc',
              color: allExpanded ? '#4f46e5' : '#475569',
              fontSize: '0.725rem',
              fontWeight: 600,
              cursor: 'pointer',
              whiteSpace: 'nowrap',
              transition: 'all 0.15s ease',
            }}
          >
            <Layers size={13} />
            <span>{allExpanded ? 'Tutup Variasi' : 'Buka Variasi'}</span>
          </button>

          {!isMobile && <div style={{ height: '20px', width: '1px', background: '#e2e8f0', margin: '0 2px' }} />}

          {/* Tombol Simpan */}
          <button
            type="button"
            onClick={handleSaveAll}
            disabled={isSaving || (!isDirty && !saveSuccess)}
            style={{
              height: '34px',
              display: 'inline-flex',
              alignItems: 'center',
              gap: '0.4rem',
              padding: '0 0.95rem',
              fontSize: '0.75rem',
              fontWeight: 700,
              borderRadius: '8px',
              border: 'none',
              background: saveSuccess
                ? 'linear-gradient(135deg, #10b981, #059669)'
                : isDirty
                ? 'linear-gradient(135deg, #4f46e5, #7c3aed)'
                : '#e2e8f0',
              color: (!isDirty && !saveSuccess) ? '#94a3b8' : '#ffffff',
              cursor: (!isDirty && !saveSuccess) ? 'not-allowed' : 'pointer',
              boxShadow: isDirty ? '0 2px 6px rgba(79, 70, 229, 0.28)' : 'none',
              whiteSpace: 'nowrap',
              transition: 'all 0.2s ease',
            }}
          >
            {isSaving ? (
              <>
                <Loader2 size={13} style={{ animation: 'spin 1s linear infinite' }} />
                <span>Menyimpan...</span>
              </>
            ) : saveSuccess ? (
              <>
                <CheckCircle2 size={13} />
                <span>Tersimpan!</span>
              </>
            ) : (
              <>
                <Save size={13} />
                <span>Simpan{isDirty ? ' •' : ''}</span>
              </>
            )}
          </button>
        </div>
      </div>

      {/* ── Table Container (Separate Card Filling Remaining Space) ── */}
      <div
        className="modern-table-wrapper"
        style={{
          flex: 1,
          minHeight: 0,
          background: '#ffffff',
          borderRadius: '12px',
          border: '1px solid #e2e8f0',
          boxShadow: '0 1px 3px rgba(0, 0, 0, 0.04), 0 1px 2px rgba(0, 0, 0, 0.02)',
          overflow: 'hidden',
          display: 'flex',
          flexDirection: 'column',
        }}
      >
        <div style={{ flex: 1, minHeight: 0, overflow: 'auto' }}>
          <table
            className="modern-table compact-table"
            style={{
              width: '100%',
              minWidth: isMobile ? '680px' : '100%',
              borderCollapse: 'separate',
              borderSpacing: 0,
            }}
          >
            <thead style={{ position: 'sticky', top: 0, zIndex: 10 }}>
              <tr>
                <th style={{ width: '45px', textAlign: 'center' }}>No</th>
                <th style={{ width: '80px', textAlign: 'center' }}>Platform</th>
                <th style={{ textAlign: 'left' }}>SKU / Produk</th>
                <th style={{ width: '140px', textAlign: 'center' }}>Variasi</th>
                <th style={{ width: '200px', textAlign: 'right' }}>Harga Pokok (HPP)</th>
                <th style={{ width: '110px', textAlign: 'center' }}>Status</th>
              </tr>
            </thead>
            <tbody>
              {filteredSkus.length === 0 ? (
                <tr>
                  <td colSpan={6} style={{ textAlign: 'center', padding: '3.5rem 1rem', color: '#94a3b8' }}>
                    <Filter size={36} strokeWidth={1.5} style={{ margin: '0 auto 0.5rem', opacity: 0.5 }} />
                    <div style={{ fontSize: '0.875rem', fontWeight: 600, color: '#475569' }}>Tidak ada SKU yang cocok</div>
                    <p style={{ fontSize: '0.75rem', margin: '0.25rem 0 0.75rem' }}>Coba ubah kata kunci pencarian atau filter status</p>
                    {(searchQuery || filterMode !== 'all') && (
                      <button
                        type="button"
                        onClick={() => { setSearchQuery(''); setFilterMode('all'); }}
                        style={{
                          padding: '0.35rem 0.75rem',
                          borderRadius: '6px',
                          border: '1px solid #e2e8f0',
                          background: '#f8fafc',
                          fontSize: '0.75rem',
                          fontWeight: 600,
                          cursor: 'pointer',
                        }}
                      >
                        Reset Filter
                      </button>
                    )}
                  </td>
                </tr>
              ) : (
                filteredSkus.map(({ sellerSku, variations, noSku, productName }, idx) => {
                  const isExpanded = expandedSkus.has(sellerSku);
                  const mainModalValue = modalValues[sellerSku] || '';
                  const variationCount = variations.length;
                  const anyVariationFilled = hasAnyVariationFilled(sellerSku);
                  const filledCount = filledVariationCountBySku.get(sellerSku) || 0;
                  const isInvalid = invalidSkus.has(sellerSku);
                  const variationTypes = getVariationTypes(variations);
                  const bulk = bulkInputs[sellerSku] || { selections: [], value: '' };
                  const chInfo = getChannelIcon(sellerSku, variations);
                  const fillStatus = getSkuFillStatus(sellerSku, variations);
                  const isFlashSaved = flashSaved === sellerSku;
                  const displayName = noSku
                    ? (productName || sellerSku.replace('__NSKU__', ''))
                    : sellerSku;

                  return (
                    <React.Fragment key={sellerSku}>
                      <tr
                        className={`im-table-row ${isFlashSaved ? 'im-row-flash' : ''}`}
                        style={{
                          background: isExpanded ? 'rgba(99, 102, 241, 0.04)' : undefined,
                          transition: 'background 0.15s ease',
                        }}
                      >
                        {/* 1. No */}
                        <td style={{ textAlign: 'center', color: '#94a3b8', fontWeight: 600, fontSize: '0.75rem' }}>
                          {idx + 1}
                        </td>

                        {/* 2. Platform / Channel */}
                        <td style={{ textAlign: 'center' }}>
                          {chInfo ? (
                            <img
                              src={chInfo.iconSrc}
                              alt={chInfo.channel}
                              title={chInfo.channel}
                              style={{ width: '20px', height: '20px', objectFit: 'contain', verticalAlign: 'middle' }}
                            />
                          ) : (
                            <span style={{ color: '#cbd5e1' }}>—</span>
                          )}
                        </td>

                        {/* 3. SKU / Produk */}
                        <td style={{ maxWidth: '380px' }}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: '0.45rem', flexWrap: 'wrap' }}>
                            {noSku && (
                              <span
                                style={{
                                  background: 'linear-gradient(135deg, #f59e0b, #d97706)',
                                  color: '#fff',
                                  fontSize: '0.625rem',
                                  fontWeight: 700,
                                  padding: '0.1rem 0.4rem',
                                  borderRadius: '4px',
                                  letterSpacing: '0.02em',
                                }}
                              >
                                Tanpa SKU
                              </span>
                            )}
                            <span
                              style={{
                                fontWeight: 700,
                                fontSize: '0.8125rem',
                                color: '#0f172a',
                                letterSpacing: '-0.01em',
                              }}
                            >
                              {displayName}
                            </span>
                          </div>
                          {!noSku && productName && productName !== sellerSku && (
                            <div
                              style={{
                                fontSize: '0.7rem',
                                color: '#64748b',
                                overflow: 'hidden',
                                textOverflow: 'ellipsis',
                                whiteSpace: 'nowrap',
                                marginTop: '1px',
                              }}
                              title={productName}
                            >
                              {productName}
                            </div>
                          )}
                        </td>

                        {/* 4. Variasi */}
                        <td style={{ textAlign: 'center' }}>
                          {variationCount <= 1 ? (
                            <span style={{ color: '#94a3b8', fontSize: '0.75rem', fontWeight: 500 }}>
                              Tunggal
                            </span>
                          ) : (
                            <button
                              type="button"
                              onClick={() => toggleExpand(sellerSku)}
                              className={`im-var-badge ${isExpanded ? 'active' : ''}`}
                              title={isExpanded ? "Tutup rincian variasi" : "Buka rincian variasi"}
                            >
                              <Layers size={11} />
                              <span>{variationCount} variasi</span>
                              {isExpanded ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
                            </button>
                          )}
                        </td>

                        {/* 5. Nilai HPP */}
                        <td style={{ textAlign: 'right' }}>
                          {variationCount <= 1 || !anyVariationFilled ? (
                            <div style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}>
                              <input
                                type="text"
                                inputMode="numeric"
                                pattern="[0-9]*"
                                placeholder="Rp0"
                                className="im-table-input"
                                value={mainModalValue}
                                onInput={(e) => handleMainInputChange(sellerSku, e)}
                                onKeyDown={handleInputKeyDown}
                              />
                            </div>
                          ) : (
                            <button
                              type="button"
                              onClick={() => toggleExpand(sellerSku)}
                              className="im-multi-badge"
                              title="Klik untuk melihat atau mengubah HPP per variasi"
                            >
                              <span>Multi-variasi ({filledCount}/{variationCount})</span>
                              {isExpanded ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
                            </button>
                          )}
                        </td>

                        {/* 6. Status */}
                        <td style={{ textAlign: 'center' }}>
                          {fillStatus === 'filled' ? (
                            <span className="im-status-chip im-status-filled">
                              <CheckCircle2 size={12} /> Terisi
                            </span>
                          ) : fillStatus === 'partial' ? (
                            <span className="im-status-chip im-status-partial">
                              <AlertTriangle size={12} /> {filledCount}/{variationCount}
                            </span>
                          ) : (
                            <span className="im-status-chip im-status-empty">
                              <Circle size={10} /> Belum
                            </span>
                          )}
                        </td>
                      </tr>

                      {/* Sub-Rows: Expanded Variations */}
                      {isExpanded && variationCount > 1 && (
                        <tr>
                          <td colSpan={6} style={{ padding: 0, borderBottom: '2px solid #cbd5e1' }}>
                            <div className="im-expanded-box">
                              {/* Warning if invalid */}
                              {isInvalid && (
                                <div
                                  style={{
                                    background: '#fff1f2',
                                    border: '1px solid #fecaca',
                                    color: '#e11d48',
                                    padding: '0.4rem 0.75rem',
                                    borderRadius: '6px',
                                    fontSize: '0.725rem',
                                    fontWeight: 600,
                                    marginBottom: '0.5rem',
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: '0.4rem',
                                  }}
                                >
                                  <AlertTriangle size={13} />
                                  <span>Perhatian: Harap isi seluruh nilai variasi produk ini ({filledCount} dari {variationCount} terisi)</span>
                                </div>
                              )}

                              {/* Bulk Edit Bar (Isi Masal) */}
                              <div className="im-bulk-bar-modern">
                                <div style={{ display: 'flex', alignItems: 'center', gap: '0.35rem', color: '#4f46e5', fontWeight: 700, fontSize: '0.75rem' }}>
                                  <Zap size={14} />
                                  <span>Isi Masal:</span>
                                </div>

                                {variationTypes.length > 0 &&
                                  variationTypes.map(({ values }, vIdx) => (
                                    <select
                                      key={vIdx}
                                      value={bulk.selections[vIdx] || 'Semua Variasi'}
                                      onChange={(e) => handleBulkDropdownChange(sellerSku, vIdx, e.target.value)}
                                      style={{
                                        height: '28px',
                                        fontSize: '0.75rem',
                                        padding: '0 0.5rem',
                                        borderRadius: '6px',
                                        border: '1px solid #cbd5e1',
                                        background: '#ffffff',
                                        color: '#0f172a',
                                        outline: 'none',
                                        cursor: 'pointer',
                                      }}
                                    >
                                      <option value="Semua Variasi">Semua</option>
                                      {values.map((val) => (
                                        <option key={val} value={val}>
                                          {val}
                                        </option>
                                      ))}
                                    </select>
                                  ))}

                                <input
                                  type="text"
                                  inputMode="numeric"
                                  pattern="[0-9]*"
                                  placeholder="Rp0"
                                  value={bulk.value}
                                  onChange={(e) => handleBulkValueChange(sellerSku, e)}
                                  onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                      e.preventDefault();
                                      applyBulkInput(sellerSku);
                                    }
                                  }}
                                  style={{
                                    width: '120px',
                                    height: '28px',
                                    padding: '0 0.5rem',
                                    fontSize: '0.775rem',
                                    fontWeight: 600,
                                    textAlign: 'right',
                                    borderRadius: '6px',
                                    border: '1px solid #cbd5e1',
                                    background: '#ffffff',
                                    color: '#0f172a',
                                    outline: 'none',
                                  }}
                                />

                                <button
                                  type="button"
                                  onClick={() => applyBulkInput(sellerSku)}
                                  disabled={!bulk.value}
                                  style={{
                                    height: '28px',
                                    display: 'inline-flex',
                                    alignItems: 'center',
                                    gap: '0.3rem',
                                    padding: '0 0.65rem',
                                    fontSize: '0.725rem',
                                    fontWeight: 700,
                                    borderRadius: '6px',
                                    border: 'none',
                                    background: bulk.value ? 'linear-gradient(135deg, #4f46e5, #7c3aed)' : '#e2e8f0',
                                    color: bulk.value ? '#ffffff' : '#94a3b8',
                                    cursor: bulk.value ? 'pointer' : 'not-allowed',
                                    transition: 'all 0.15s ease',
                                    whiteSpace: 'nowrap',
                                  }}
                                >
                                  <Check size={12} />
                                  <span>Terapkan</span>
                                </button>
                              </div>

                              {/* Variation Sub-Table */}
                              <table className="im-subtable">
                                <thead>
                                  <tr>
                                    <th style={{ width: '40px', textAlign: 'center' }}>#</th>
                                    <th style={{ textAlign: 'left' }}>Nama Variasi</th>
                                    <th style={{ textAlign: 'left' }}>SKU ID</th>
                                    <th style={{ width: '180px', textAlign: 'right' }}>Nilai HPP</th>
                                    <th style={{ width: '90px', textAlign: 'center' }}>Status</th>
                                  </tr>
                                </thead>
                                <tbody>
                                  {variations
                                    .filter(({ variation }) => {
                                      if (variationTypes.length === 0) return true;
                                      const selections = bulk.selections || [];
                                      let parts = variation.split(' / ');
                                      if (parts.length === 1) parts = variation.split(',');
                                      parts = parts.map((p) => p.trim());
                                      if (parts.length !== variationTypes.length) return true;
                                      for (let i = 0; i < variationTypes.length; i++) {
                                        const sel = selections[i] || 'Semua Variasi';
                                        if (sel !== 'Semua Variasi' && sel !== parts[i]) return false;
                                      }
                                      return true;
                                    })
                                    .map(({ skuId, variation }, subIdx) => {
                                      const key = sellerSku + '||' + skuId + '||' + variation;
                                      const val = modalValues[key] || '';
                                      return (
                                        <tr
                                          key={key}
                                          style={{
                                            background: val ? '#f0fdf4' : undefined,
                                          }}
                                        >
                                          <td style={{ textAlign: 'center', color: '#94a3b8', fontSize: '0.725rem' }}>
                                            {subIdx + 1}
                                          </td>
                                          <td style={{ fontWeight: 600, color: '#1e293b' }}>
                                            {variation || 'Default'}
                                          </td>
                                          <td style={{ color: '#64748b', fontSize: '0.725rem', fontFamily: 'monospace' }}>
                                            {skuId || '—'}
                                          </td>
                                          <td style={{ textAlign: 'right' }}>
                                            <input
                                              type="text"
                                              inputMode="numeric"
                                              pattern="[0-9]*"
                                              placeholder="Rp0"
                                              className="im-table-input"
                                              style={{ height: '28px', fontSize: '0.775rem' }}
                                              value={val}
                                              onInput={(e) => handleVariationInputChange(sellerSku, skuId, variation, e)}
                                              onKeyDown={handleInputKeyDown}
                                            />
                                          </td>
                                          <td style={{ textAlign: 'center' }}>
                                            {val ? (
                                              <span style={{ color: '#059669', fontSize: '0.725rem', fontWeight: 600, display: 'inline-flex', alignItems: 'center', gap: '3px' }}>
                                                <CheckCircle2 size={12} /> Ok
                                              </span>
                                            ) : (
                                              <span style={{ color: '#94a3b8', fontSize: '0.725rem' }}>
                                                Kosong
                                              </span>
                                            )}
                                          </td>
                                        </tr>
                                      );
                                    })}
                                </tbody>
                              </table>
                            </div>
                          </td>
                        </tr>
                      )}
                    </React.Fragment>
                  );
                })
              )}
            </tbody>
          </table>
        </div>

        {/* ── Integrated Footer ── */}
        <div
          style={{
            flexShrink: 0,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            flexWrap: 'wrap',
            gap: '0.4rem',
            padding: isMobile ? '0.35rem 0.6rem' : '0.4rem 0.85rem',
            background: '#fcfdfe',
            borderTop: '1px solid #eef0f6',
            fontSize: isMobile ? '0.7rem' : '0.75rem',
          }}
        >
          <div style={{ color: '#64748b' }}>
            Menampilkan <strong style={{ color: '#0f172a' }}>{filteredSkus.length}</strong> dari{' '}
            <strong style={{ color: '#0f172a' }}>{stats.total}</strong> SKU produk •{' '}
            <span style={{ color: progressPercent === 100 ? '#059669' : '#4f46e5', fontWeight: 600 }}>
              {progressPercent}% Terisi ({stats.filled} selesai)
            </span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            {isDirty ? (
              <>
                <span style={{ color: '#d97706', fontWeight: 600, fontSize: '0.725rem' }}>
                  • Ada perubahan yang belum disimpan
                </span>
                <button
                  type="button"
                  onClick={handleSaveAll}
                  disabled={isSaving}
                  style={{
                    padding: '0.25rem 0.65rem',
                    borderRadius: '6px',
                    border: 'none',
                    background: '#4f46e5',
                    color: '#ffffff',
                    fontSize: '0.725rem',
                    fontWeight: 700,
                    cursor: 'pointer',
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: '4px',
                  }}
                >
                  <Save size={11} />
                  Simpan
                </button>
              </>
            ) : (
              <span style={{ color: '#059669', fontSize: '0.725rem', display: 'inline-flex', alignItems: 'center', gap: '4px' }}>
                <CheckCircle2 size={12} />
                Seluruh data tersimpan
              </span>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default InputModal;
